contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(newOwner != address(0));
        // read initial owner
        address beforeOwner = c.owner();

        // try to transfer ownership from this contract (msg.sender to c is this contract)
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterOwner = c.owner();

        // General rule: if call did not revert then owner must have changed to newOwner;
        // if it reverted then owner must be unchanged (still beforeOwner).
        assert((!reverted && afterOwner == newOwner) || (reverted && afterOwner == beforeOwner));
    }
    receive() external payable {}
}

