contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address newOwner) public payable {
        require(caller != address(0));
        // We need to set up owner so that sometimes caller is the owner and sometimes not.
        // The deploying account of C set its initial owner; here we can attempt to make `caller` the owner
        // by calling transferOwnership from this contract only if this contract is the owner.
        // First, record original owner.
        address origOwner = c.owner();

        // If this test contract is the current owner, transfer ownership to `caller` so that the upcoming
        // transferOwnership test call from this contract will simulate a call as owner -> caller.
        bool setupReverted;
        if (origOwner == address(this)) {
            // this call should not revert because msg.sender == owner
            try c.transferOwnership(caller) {
                setupReverted = false;
            } catch {
                setupReverted = true;
            }
        } else {
            setupReverted = false; // nothing done
        }

        // Now observe owner after potential setup
        address midOwner = c.owner();

        // Attempt to call transferOwnership from this contract to set owner to newOwner.
        // Capture whether it reverts. According to the contract P, this will succeed iff msg.sender == owner.
        bool callReverted;
        try c.transferOwnership(newOwner) {
            callReverted = false;
        } catch {
            callReverted = true;
        }

        // Read final owner
        address finalOwner = c.owner();

        // General rule:
        // If the call did not revert then this contract was owner before the call and finalOwner == newOwner.
        // If the call reverted then this contract was not owner before the call and finalOwner == midOwner.
        assert((!callReverted && midOwner == address(this) && finalOwner == newOwner) || (callReverted && midOwner != address(this) && finalOwner == midOwner));
    }
    receive() external payable {}
}

