    function run(address possibleNewOwner, address caller) public payable {
        require(true);
        // record current owner
        address beforeOwner = c.owner();

        // Try calling transferOwnership as if this contract (the owner or not) calls it.
        // Because the test contract is the msg.sender when calling c, we simulate two cases:
        // - If beforeOwner == address(this), the call should succeed and set owner = possibleNewOwner.
        // - Otherwise the call should revert and owner should remain beforeOwner.

        bool reverted;
        // perform the call and capture revert
        try c.transferOwnership(possibleNewOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterOwner = c.owner();

        // General rule: if the test contract was the owner before the call, the call must not revert
        // and owner becomes possibleNewOwner; otherwise the call must revert and owner stays the same.
        assert(
            (beforeOwner == address(this) && !reverted && afterOwner == possibleNewOwner)
            ||
            (beforeOwner != address(this) && reverted && afterOwner == beforeOwner)
        );
    }
    receive() external payable { }
