contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwnerForSetup) public payable {
        require(true);
        // Setup: record original owner
        address ownerBefore = c.owner();

        // If this test contract is not the owner, try to make it the owner by calling transferOwnership from the current owner.
        // But we cannot make external accounts call c; we can only act as this contract. So only attempt transfer if already owner.
        // Record whether we were owner before attempting any state-changing call.
        bool wasOwner = (ownerBefore == address(this));

        // If we are owner, perform a legitimate ownership transfer to newOwnerForSetup to change state; otherwise skip.
        if (wasOwner) {
            // This call should succeed (no try/catch) when we are the owner.
            c.transferOwnership(newOwnerForSetup);
        }

        // After optional transfer, read current owner
        address ownerAfterSetup = c.owner();

        // Now attempt to call owned(), which uses onlyOwner modifier and has an empty body.
        // Capture whether it reverts.
        bool reverted;
        try c.owned() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Final observed owner
        address ownerFinal = c.owner();

        // General rule to assert:
        // - owned() must succeed (not revert) iff msg.sender (this contract) equals the current owner at the moment of the call.
        // - Regardless of whether owned() reverts, the owner value must not change as a result of calling owned().
        assert(
            ((ownerAfterSetup == address(this)) == (!reverted))
            &&
            (ownerFinal == ownerAfterSetup)
        );
    }
    receive() external payable { }
}

